  str_n29_detective_clue_name_23 = "muñeca desgastada",
  str_n29_detective_clue_name_24 = "Fiesta Nocturna",
  str_n29_detective_clue_name_25 = "Ensayo",
  str_n29_detective_clue_name_26 = "limpieza repentina",
  str_n29_detective_clue_name_27 = "mocoso no deseado",
  str_n29_detective_clue_name_28 = "Sustitución",
  str_n29_detective_clue_name_29 = "otro registro",
  str_n29_detective_clue_name_30 = "Libro de guiones sucios",
  str_n29_detective_clue_name_31 = "Hacha",
  str_n29_detective_clue_name_32 = "Extraviado",
  str_n29_detective_clue_name_33 = "Un asunto importante",
  str_n29_detective_clue_desc_1 = "Hati escucha dos voces extrañas hablando cuando está medio dormida.\nDicen que es una niña solitaria, con una personalidad obstinada y poco sociable que a la mayoría de la gente le desagrada.\nTambién dicen que es demasiado fuerte y que no puede controlarse, y que a menudo prende fuego a las cosas.\nNadie querría nunca un niño así.",
  str_n29_detective_clue_desc_2 = "Los niños impopulares son llamados \"mocosos\" en el orfanato.\nDicen que no tiene sentido aferrarse a esos niños y que es hora de enviar Hati lejos.",
  str_n29_detective_clue_desc_3 = "La señorita Niñera cuenta Hati que el orfanato es su nuevo hogar.\nSu madre no puede estar con ella en este momento... pero la señorita Childminder sí.\nAquí hay muchos niños agradables y la señorita Niñera cree que Hati podrá vivir feliz con todos.",
  str_n29_detective_clue_desc_4 = "El limpiador dice Hati que los orfanatos son lugares que acogen a niños no deseados.\nY la mamá de Hati la dejó aquí debe ser porque la odia.\nA nadie le importan los niños sin padres, son como piedras al costado del camino, y la gente simplemente los echa fuera del camino.\nA partir de ahora, todo lo que queda por delante Hati es una vida vivida en un infierno constante.",
  str_n29_detective_clue_desc_5 = "Estos guantes de aspecto familiar están húmedos en la superficie.\nHati había visto guantes como estos antes: su madre usaba guantes similares a ellos cuando limpiaba.\nHati recordó que su mamá dijo que los guantes hacían las cosas más fáciles.",
  str_n29_detective_clue_desc_6 = "Una pequeña bolsa de pan.\nParece que entró algo de agua y ahora el pan está empapado y huele a humedad.\nHati dice que el pan que le daba su mamá siempre olía tan delicioso y era tan suave.\nParece que extraña a su madre...",
  str_n29_detective_clue_desc_7 = "Esa niña dice que tiene muchos amiguitos divertidos en el orfanato.\nTodos juegan con juguetes, dibujan, comen y toman siestas juntos todos los días. ¡Nunca se vuelve aburrido aquí!\nPero también hay algunos niños malos... sería mejor si Hati se mantuvo alejado de ellos.",
  str_n29_detective_clue_desc_8 = "¿Sabes lo que es un \"mocoso\"?\nEs un niño que no le gusta a nadie.\nComo El Rey Malvado. ¡Todos piensan que es un verdadero dolor en el trasero, y su pequeño y viscoso parásito también!\nPero nadie les tiene miedo a esos mocosos porque todo el mundo sabe que los mocosos obtienen lo que se merecen.\nLos niños buenos reciben dulces y los niños malos son castigados. Esa chica dice que así son siempre las cosas en el orfanato.",
  str_n29_detective_clue_desc_9 = "A ese tipo le encanta vivir en el orfanato.\n¡La gran y misericordiosa Señora Directora, su compasión permitió que los niños sin hogar recibieran el cuidado y el calor de una familia!\nPero esta felicidad es fugaz.\nLos mejores niños son enviados a familias adineradas cada mes para llevar una vida sin preocupaciones. Los niños horribles son enviados a familias pobres donde nadie realmente se preocupa por ellos.\nPero está bien, ese parásito todavía tiene su mantra secreto. Mientras sigas halagando a los adultos, incluso si realmente no les gustas, al menos te dejarán en paz por un tiempo.",
  str_n29_detective_clue_desc_10 = "¡El Rey Malvado dice que es el personaje principal del orfanato!\nEs el más popular, todo el mundo tiene que prestarle atención, ¡y todos los juguetes también le pertenecen a él!\nMira, incluso lo eligieron para el papel principal en la obra de teatro mañana por la noche... ¡Bueno, es natural, ya que él es el único que importa en este lugar!\nEn cuanto a ese parásito, la buena chica y los adultos en el escenario con él, son solo accesorios, para que el personaje principal se destaque aún más.\nPero esa chica es incluso más popular que el Rey Malvado... ¡y él no lo soporta!",
  str_n29_detective_clue_desc_11 = "Miss Childminder dice que a los adultos les gustan los niños sensatos.\nMientras Hati ayuda a más personas, ¡a todos definitivamente les gustará!",
  str_n29_detective_clue_desc_12 = "Un sobre perfecto y hermoso con un sello rojo brillante...\nEsa carta parece tan noble y fuera de lugar en este orfanato ruinoso como la Señora Directora.",
  str_n29_detective_clue_desc_13 = "El repartidor afirma que perdió algo.\nDescribe que es algo blanco y suave que a los niños les encantaría.\nEn cuanto a qué es exactamente... bueno, ese anciano tiene muy mala memoria, ¡lo olvidó por completo!",
  str_n29_detective_clue_desc_14 = "Ese hombre con un poco de joroba dijo que era un inversionista en el orfanato.\nMira, la lista de niños en su mano prueba sus palabras. Todos los niños que alguna vez han estado aquí han sido registrados en él.\nDice que ha invertido mucho dinero para que todos puedan vivir una buena vida aquí, para que todos tengamos ropa y comida para comer.",
  str_n29_detective_clue_desc_15 = "Miss Childminder está muy estresada porque su salario es muy bajo.\nPero parece que ella es la única que tiene problemas de dinero en este lugar. Dice que hasta el conserje se ríe de ella por ser tan pobre...\nElla es tan amable con todos y obviamente trabaja tan duro, así que ¿por qué su vida no es tan buena como la de ese limpiador perezoso?\nMiss Childminder dice que es porque los adultos siempre hacen a un lado a las personas que no les agradan.",
  str_n29_detective_clue_desc_16 = "Hay un dibujo a crayón en la cama del Rey Malvado.\nEs una foto de un niño tirado en algún lugar donde se guardan un montón de cosas, con una cosa sucia y blanquecina al lado...\nHonestamente, la imagen es un desastre, eso es todo. Hati realmente podría darse cuenta.",
  str_n29_detective_clue_desc_17 = "Ese bolso con el agujero parece que se usó durante mucho tiempo.\nEs tan ligero que incluso hace un crujido cuando lo agitas.",
  str_n29_detective_clue_desc_18 = "Esta imagen de crayón está en el suelo afuera.\nEs un dibujo de tres personas: una mujer que llora, un hombre enojado y un niño golpeado.",
  str_n29_detective_clue_desc_19 = "Un asqueroso corderito de juguete.\nEstá cubierto de barro, así como algunas marcas de color rojo oscuro.",
  str_n29_detective_clue_desc_20 = "Miss Childminder dice que mucha gente rica vendrá a ver la obra mañana. Adoptarán a los niños que se desempeñen bien.\nEsta recompensa es solo para niños buenos.\nHati ayuda a la señorita Childminder a encontrar su bolso, y ella dice Hati incluso debería intentar actuar en el escenario también.",
  str_n29_detective_clue_desc_21 = "Ese repartidor dice que deberíamos darles a las personas que cometen errores la oportunidad de compensarlos en privado.\nEsa es la buena voluntad de los adultos.\nEl mundo de los adultos es complicado, por lo que intentarán resolver los problemas de manera pacífica y sensata. Es por el bien de todos.",
  str_n29_detective_clue_desc_22 = "¿Sabes por qué vivir en un orfanato es tan feliz?\nPorque todos los adultos aquí quieren mucho a los niños.\nAquí todos trabajan para darnos su amor sin esperar nada a cambio.\nPor eso tenemos que aprender a ser agradecidos.",
  str_n29_detective_clue_desc_23 = "Una vieja muñeca rota.\nEs obvio que a quienquiera que haya pertenecido esto, lo amaba mucho.\nSupongo que no importa cuánto ames algo, se volverá viejo y se romperá después de que pase el tiempo suficiente.",
  str_n29_detective_clue_desc_24 = "El orfanato organiza una fiesta al final de cada mes. Es uno de los eventos más importantes aquí.\nLa mayoría de los niños suelen portarse bien en estas fiestas y tratan de parecer niños buenos y populares para mostrarles a todos su mejor lado.\n\nDebe ser porque otro evento importante tiene lugar poco después de la fiesta de fin de mes: el día de la adopción, cuando los niños buenos y malos abandonan el orfanato para ir a sus nuevos hogares.",
  str_n29_detective_clue_desc_25 = "Hati ¡tiene que comenzar el ensayo ahora para la obra para asegurarse de que se aprendió todas sus líneas antes de la presentación!\nTodos están ocupados preparándose para la fiesta, así que nadie tiene tiempo para ayudar. Hati...\nHati ahora tiene que ir solo detrás del escenario para encontrar accesorios y luego ir a la sala del director para encontrar el guión.",
  str_n29_detective_clue_desc_26 = "Temprano esta mañana, ese parásito vio al conserje limpiando la cama del Rey Malvado y llevando sus cosas a la puerta trasera para dárselas al repartidor.\n¿A dónde podría haber ido El Rey Malvado?",
  str_n29_detective_clue_desc_27 = "Una personalidad podrida, un comportamiento vil, una racha violenta impredecible...\nNadie querría un mocoso así.\nEs por eso que nadie adoptaría al Rey Malvado, ¿entiendes?",
  str_n29_detective_clue_desc_28 = "El Rey Malvado se fue, y Hati tomó su lugar como el personaje principal.\nEse repartidor dijo Hati debería pasar menos tiempo preocupándose por The Wicked King y más tiempo preocupándose por sí misma.",
  str_n29_detective_clue_desc_29 = "Este registro es muy similar al que lleva consigo el inversor.\nLa única diferencia es que todas estas marcas están al lado de los nombres de los niños.\nAlgunos están tachados y otros marcados.\nVaya a la página más reciente y verá el nombre de Hati en la página. El nombre del Rey Malvado también está en él.\nEl Rey Malvado, Hati, el aguafiestas, la buena chica... Todos están ahí, y todos están marcados con cruces rojas brillantes. ¿Qué podría significar eso?",
  str_n29_detective_clue_desc_30 = "La mitad de un libro de guiones sucio está manchado con tinta de color rojo oscuro.\nLa tinta huele un poco a pescado... que raro.",
  str_n29_detective_clue_desc_31 = "Un hacha corta.\nTiene muchas marcas de óxido, pero la hoja está pulida y muy afilada.\nUna cosa peligrosa como esta no debería usarse como accesorio de rendimiento...",
  str_n29_detective_clue_desc_32 = "Hati hace enojar a la señorita Niñera.\nLa señorita Niñera dice que Hati no debería tratar las cosas peligrosas tan descuidadamente.\nSolo los perros callejeros recogen cosas sin pensar.\nEs Hati un perro callejero?",
  str_n29_detective_clue_desc_33 = "La chica le dice algo muy serio a Hati sobre cómo debería tratar de diferenciar entre lo que es importante y lo que no lo es.\nNo representamos obras de teatro solo para ser buenos pequeños actores. Se trata de convertirse en niños lindos, simpáticos e inteligentes, convertirse en un niño que la gente esté dispuesta a llevarse a casa.\nComparado con esto, nada más importa.\nEstas palabras suenan un poco familiares. Oh, sí, mamá solía decir eso sobre los pasteles en el escaparate.",
  str_n29_detective_fragment_name_1 = "La situación en el orfanato",
  str_n29_detective_fragment_name_2 = "El merecido del mocoso",
  str_n29_detective_fragment_name_3 = "Un orfanato de amor",
  str_n29_detective_fragment_name_4 = "La fiesta especial de la noche",
  str_n29_detective_fragment_name_5 = "El paradero del rey malvado",
  str_n29_detective_fragment_name_6 = "Hati el mocoso",
  str_n29_detective_fragment_name_7 = "monstruos reales",
  str_n29_detective_fragment_desc_1 = "Este orfanato es un lugar para niños sin hogar.\nNo es particularmente grande y las instalaciones están en ruinas, pero la señorita Childminder hace todo lo posible para cuidarnos.\nHay gente buena y mala entre los niños y los adultos. La mamá de Hati dijo una vez que el mundo exterior también es así, y que Hati necesita aprender a adaptarse a ella.",
  str_n29_detective_fragment_desc_2 = "Todos odian al Rey Malvado.\nEs agresivo, descuidado y le gusta intimidar a todos.\nPero a nadie le molesta demasiado. Eso es porque los niños malos son expulsados al final de cada mes. Solo los niños buenos se quedan en el orfanato y son enviados a buenas familias.",
  str_n29_detective_fragment_desc_3 = "Los adultos son buenos para delegar y cooperar.\nEn este orfanato cariñoso, algunas personas son responsables de invertir, otras de darnos amor y otras de ganar dinero en tiempos desesperados.\nSin embargo, parece que solo la responsable de darnos amor es criticada por los otros adultos y, como resultado, su vida se ha vuelto miserable.",
  str_n29_detective_fragment_desc_4 = "Al final de cada mes, el orfanato organiza un evento especial: una fiesta nocturna.\nEn la fiesta, los niños actúan para algunos adultos que nunca antes habían visto. Los niños que mejor se desempeñan son adoptados por familias adineradas.\nLa actuación de este mes es una obra de teatro. El Rey Malvado hace el papel de héroe, la chica buena hace de princesa, y el aguafiestas y la Señorita Niñera hacen de aldeanos. La buena chica le quita todo el protagonismo a The Wicked King, y eso realmente lo enoja.",
  str_n29_detective_fragment_desc_5 = "Antes de desaparecer, el Rey Malvado estaba celoso de la buena chica e iba a hacerle algo malo. Le robó la muñeca y se coló en el carruaje del repartidor. Pero después de ver lo que vio, finalmente cambió de opinión. Después de huir a toda prisa, dibujó lo que vio.\nAyer, el repartidor dijo que resolvería el problema en privado para evitar la vergüenza. Hoy, El Rey Malvado desapareció.\nEl repartidor dice que fue adoptado. Pero mirando este sucio libro de guiones, tal vez el conserje tenía razón...",
  str_n29_detective_fragment_desc_6 = "Al principio, a la gente no le gustaba Hati.\nHati se esforzó mucho para hacer felices a todos.\nPero incluso ahora... a la gente todavía no le gusta.",
  str_n29_detective_fragment_desc_7 = "Tratan en secreto con los niños malos.\nEsos adultos que solo se preocupan por el dinero se están beneficiando de él.\nLos niños problemáticos serán tratados lo antes posible, lo que significa que los días de Hati están contados.",
  str_n29_detective_end_name_1 = "Adiós, mocoso",
  str_n29_detective_end_name_2 = "Adiós, Pesadilla",
  str_n29_detective_end_desc_1 = "Ladrones, perros callejeros, pequeños monstruos...\nNadie juega contigo. A nadie le gustas.\n¡Desaparece de aquí, rápido!",
  str_n29_detective_end_desc_2 = "Huir.\nCon libertad, siempre mirando hacia adelante.\nNunca mirar hacia atrás.",
  str_n29_detective_point_lockname_3 = "Una mujer",
  str_n29_detective_point_lockname_4 = "niño desaliñado",
  str_n29_detective_point_lockname_5 = "niño salvaje",
  str_n29_detective_point_lockname_6 = "Anciana",
  str_n29_detective_point_lockname_7 = "El hombre gordo",
  str_n29_detective_point_lockname_8 = "El caballero jorobado",
  str_n29_detective_point_lockname_9 = "Un lugar para dormir",
  str_n29_detective_point_lockname_10 = "El césped",
  str_n29_detective_point_lockname_11 = "Detras de la cortina",
  str_n29_detective_point_lockname_12 = "Una Habitación Diferente",
  str_n29_detective_point_name_1 = "Niñera",
  str_n29_detective_point_name_2 = "Limpiador",
  str_n29_detective_point_name_3 = "Chica amable",
  str_n29_detective_point_name_4 = "Lacayo",
  str_n29_detective_point_name_5 = "el rey malvado",
  str_n29_detective_point_name_6 = "viejo decano",
  str_n29_detective_point_name_7 = "Mensajero",
  str_n29_detective_point_name_8 = "Inversor",
  str_n29_detective_point_name_9 = "El dormitorio",
  str_n29_detective_point_name_10 = "El patio",
  str_n29_detective_point_name_11 = "Entre bastidores",
  str_n29_detective_point_name_12 = "La oficina del director",
  str_n29_detective_point_lockdesc_3 = "El otro niño en la habitación.\n\n<color=#902121>Hati no quiere hablar con ella en este momento.</color>",
  str_n29_detective_point_lockdesc_4 = "Siempre sigue a los niños más duros con una sonrisa repulsiva.\n\n<color=#902121>Hati no quiere hablar con él si está bien.</color>",
  str_n29_detective_point_lockdesc_5 = "Un niño con una voz fuerte que se ve muy agresivo.\n\n<color=#902121>Manténgase alejado de él, si es posible.</color>",
  str_n29_detective_point_lockdesc_6 = "La anciana vestida de negro siempre mira Hati con desaprobación en sus ojos.\n\n<color=#902121>Será mejor que no la molestes si está bien.</color>",
  str_n29_detective_point_lockdesc_7 = "Ese gordo, ¿el carruaje a su lado le pertenece?\n\n<color=#902121>No lo molestes a menos que sea absolutamente necesario.</color>",
  str_n29_detective_point_lockdesc_8 = "Este viejecito jorobado parece bastante acomodado.\nPor alguna razón, Hati no le gusta\n\n<color=#902121>Hati no quiere hablar con él si eso no es un problema.</color>",
  str_n29_detective_point_lockdesc_9 = "Hati solía dormir acurrucada con su madre.\nMamá...\n\n<color=#902121>Hati no está de humor para explorar aquí por el momento.</color>",
  str_n29_detective_point_lockdesc_10 = "Hati nunca se le permitía salir a jugar cuando vivía con su madre.\n¿Se siente bien rodar por el césped?\nPero ninguno de los otros niños ha salido a jugar...\n\n<color=#902121>Hati es un niño bueno y obediente. Vuelve aquí solo cuando lo necesites.</color>",
  str_n29_detective_point_lockdesc_11 = "¿Qué hay detrás de la cortina?\nTengo muchas ganas de levantar el velo y ver qué hay allí.\nPero los adultos dijeron que no podemos jugar aquí...\n\n<color=#902121>Hati es un niño bueno y obediente. Vuelve aquí solo cuando lo necesites.</color>",
  str_n29_detective_point_lockdesc_12 = "Esta puerta se ve tan hermosa. Es tan grueso, y tan diferente de cualquier otro lugar.\nSin embargo, al dueño no le gusta que la gente entre aquí sin permiso...\n\n<color=#902121>Hati es un niño bueno y obediente. Vuelve aquí solo cuando lo necesites.</color>",
  str_n29_detective_point_desc_1 = "Amable señorita niñera.\nSus manos son tan delgadas y tan ásperas, como las manos de mamá.\nDe todos los adultos, ella es la única Hati confía más.\nsiempre que haya <color=#902121>algo que no se atrevería a preguntarle a nadie más, siempre puede preguntarle.</color>",
  str_n29_detective_point_desc_2 = "Un conserje al que le encanta holgazanear.\nNo le gustan los niños y siempre se burla de ellos. Hati. ¡Ella es vil!\nSin embargo, ella es la única que se atreve a decirle. Hati <color=#902121>secretos que los otros adultos no contarían.</color>",
  str_n29_detective_point_desc_3 = "Una chica que habla muy bajo y le encanta reír.\nHati sintió que tal vez podría <color=#902121>hazte amigo de ella...</color>\nSiempre parece haber algo siniestro escondido en su sonrisa, pero <color=#902121>¿Qué se puede hacer para ayudarla?</color>",
  str_n29_detective_point_desc_4 = "El adulador lacayo del Rey Malvado.\nSin embargo, <color=#902121>Al Rey Malvado no le gusta...</color>\n<color=#902121>¿Por qué parece satisfecho siguiendo al Rey Malvado?</color>",
  str_n29_detective_point_desc_5 = "Todos odian al Rey Malvado.\nÉl siempre <color=#902121>le gusta intimidar a la gente</color>, entonces, ¿por qué le gustaría a alguien?\n<color=#902121>Sin amigos, es imposible abrir tu corazón a nadie.</color>\nTal vez si fueras a <color=#902121>llámalo, él hablará contigo.</color>",
  str_n29_detective_point_desc_6 = "La anciana directora del orfanato siempre parece como si <color=#902121>le molesta absolutamente todo.</color>\nHati no le gusta cuando la mira fijamente. <color=#902121>Si tan solo ella no estuviera aquí.</color>",
  str_n29_detective_point_desc_7 = "Al repartidor del orfanato le gusta reírse a carcajadas.\nel parece <color=#902121>disfruta estar cerca de los niños</color> y charlas con Hati sobre varias cosas.\nSu <color=#902121>carro</color> es realmente muy curioso. ¿Qué podría haber dentro?",
  str_n29_detective_point_desc_8 = [[
Un inversionista en el orfanato que es <color=#902121>siempre mirando Hati.</color>
Hati no le gusta]],
  str_n29_detective_point_desc_9 = "Aquí es donde Hati y los otros niños duermen y juegan.\n<color=#902121>sus secretos</color> suele esconderse con ellos debajo de las sábanas.\n<color=#902121>señorita niñera</color> también le gusta quedarse aquí. A veces, ella se sienta aquí, suspirando.",
  str_n29_detective_point_desc_10 = "Los mayores dicen que afuera hace mal tiempo, así que no podemos salir a jugar. Pero siempre hay niños desobedientes que <color=#902121>se escabullen.</color> <color=#902121>Sr. Inversor</color> también está aquí... A Hati no le cae bien.",
  str_n29_detective_point_desc_11 = "Tos, tos... Hay mucho polvo aquí.\nEl área detrás del escenario está repleta de accesorios de actuación hechos por los niños. ¿Podría haber alguna <color=#902121>tesoros</color> escondido aquí?",
  str_n29_detective_point_desc_12 = "Hati Nunca había visto una habitación tan hermosa. ¡Pero no hay ventanas, como en la casa de Hati!\nNo hay nadie aquí ahora, así que si echas un vistazo a la <color=#902121>los secretos del viejo director</color>, alguien se enterara?",
  str_n29_detective_character_random_1 = "¿Qué pasa? ¿Tienes hambre?",
  str_n29_detective_character_random_2 = "Si alguna vez hay algo que importe, asegúrate de decírmelo.",
  str_n29_detective_character_random_3 = "Tos, tos... Está bien, no te preocupes por mí.",
  str_n29_detective_character_random_4 = "Deja de molestarme.",
  str_n29_detective_character_random_5 = "¿Para qué me buscas, perro callejero?",
  str_n29_detective_character_random_6 = "Si no tienes dinero para mí, simplemente vete.",
  str_n29_detective_character_random_7 = "¡Oye, tú!",
  str_n29_detective_character_random_8 = "Jejeje, estás aquí para charlar conmigo de nuevo, ¿verdad?",
  str_n29_detective_character_random_9 = "¿Quieres jugar conmigo?",
  str_n29_detective_character_random_10 = "¡Yo no dije nada malo de nadie!",
  str_n29_detective_character_random_11 = "¡La gran y misericordiosa Señora Directora, todos la quieren!",
  str_n29_detective_character_random_12 = "El orfanato es el mejor lugar del mundo.",
  str_n29_detective_character_random_13 = "¡Soy El Rey Glorioso, todos ustedes tienen que hacer lo que les diga!",
  str_n29_detective_character_random_14 = "Soy el chico más popular aquí, ¡todos deberían hacer lo que les digo!",
  str_n29_detective_character_random_15 = "¡Entregue sus juguetes y piérdase!",
  str_n29_detective_character_random_16 = "... ¿Puedo ayudarle?",
  str_n29_detective_character_random_17 = "Si tienes algo que decir, sé rápido.",
  str_n29_detective_character_random_18 = "Tú, retrocede. No te acerques tanto a mí.",
  str_n29_detective_character_random_19 = "Puedes preguntarme lo que quieras sobre el orfanato.",
  str_n29_detective_character_random_20 = "Jajaja, no seas tan travieso!",
  str_n29_detective_character_random_21 = "Sé agradecido por lo que tienes.",
  str_n29_detective_character_random_22 = "Tu colgante es realmente especial...",
  str_n29_detective_character_random_23 = "Hola pequeño.",
  str_n29_detective_character_random_24 = "¿No te apetece una charla?",
  str_n29_detective_character_notalk_1 = "Deja de ser pegajoso y ve a jugar con los demás.",
  str_n29_detective_character_notalk_2 = "¿Qué estás mirando? ¿Quieres que te dé una lección?",
  str_n29_detective_character_notalk_3 = "Lo siento, estoy un poco ocupado en este momento.",
  str_n29_detective_character_notalk_4 = "¿P-Por qué siempre me miras? ¡No tengo dulces conmigo!",
  str_n29_detective_character_notalk_5 = "¡Piérdete antes de que te golpee!",
  str_n29_detective_character_notalk_6 = "Estoy muy ocupado.",
  str_n29_detective_character_notalk_7 = "Muy bien, tengo trabajo que hacer. Vete a jugar a otro lado, ¿eh?",
  str_n29_detective_character_notalk_8 = "...",
  str_n29_detective_character_rightclue_1 = "¿Necesitas algo? Bien entonces.",
  str_n29_detective_character_rightclue_2 = "Tsk, si tienes algo que decir, simplemente dilo.",
  str_n29_detective_character_rightclue_3 = "Espera, ¿es esto...?",
  str_n29_detective_character_rightclue_5 = "¡¿Cómo te atreves a robarme?!",
  str_n29_detective_character_rightclue_7 = "¡Hahaha!",
  str_n29_detective_character_wrongclue_1 = "Estoy un poco ocupado ahora. ¿Podrías ir a preguntarle a alguien más?",
  str_n29_detective_character_wrongclue_2 = "Hazte a un lado. No se interponga en mi trabajo.",
  str_n29_detective_character_wrongclue_3 = "¿Qué es?",
  str_n29_detective_character_wrongclue_5 = "¿Quién dijo que podías hablar conmigo? ¡Sal de aquí!",
  str_n29_detective_character_wrongclue_7 = "No lo tengo muy claro en todo eso.",
  str_n29_detective_character_mission_1 = "Desbloquea \"Adiós, mocoso\"",
  str_n29_detective_character_mission_2 = "Desbloquea \"Adiós, Pesadilla\"",
  str_n29_detective_character_mission_3 = "Alcanza la profundidad del sueño 30%",
  str_n29_detective_character_mission_4 = "Alcanza la profundidad del sueño 60%",
