  str_n29_detective_character_mission_6 = "Completa tu primera Elucidación",
  str_n29_detective_character_mission_7 = "Completa tu segunda Elucidación",
  str_n29_detective_character_mission_8 = "Completa tu tercera Elucidación",
  str_n29_detective_character_mission_desc_1 = "Cuidadoso. Cuando huimos de lo que debemos enfrentar, a menudo nos hundimos aún más en la desesperanza.",
  str_n29_detective_character_mission_desc_2 = "Los primeros rayos del sol perforan silenciosamente la noche. Es hora de despertar, Fluffy.",
  str_n29_detective_character_mission_desc_3 = "Un cierto grado de curiosidad te hace parecer tan adorable.",
  str_n29_detective_character_mission_desc_4 = "Tal vez solo haya una delgada línea entre preguntar y ser grosero.",
  str_n29_detective_character_mission_desc_5 = "No todas las cortinas deben correrse.",
  str_n29_detective_character_mission_desc_6 = "Niño brillante, amado por todos, todos están muy orgullosos de ti.",
  str_n29_detective_character_mission_desc_7 = "Tu sabiduría está empezando a avergonzar a los adultos. Es hora de que aprendas a hacerte el tonto.",
  str_n29_detective_character_mission_desc_8 = "No todas las preguntas deben tener respuestas.",
  str_n29_detective_character_mission_name_1 = "Desbloquea el final Goodbye, Brat",
  str_n29_detective_character_mission_name_2 = "Desbloquea el final Adiós, Pesadilla",
  str_n29_detective_character_mission_name_3 = "Alcanza la profundidad del sueño 30%",
