  str_n29_detective_character_mission_name_5 = "Alcanza la profundidad del sueño 100%",
  str_n29_detective_character_mission_name_6 = "Completa tu primera Elucidación",
  str_n29_detective_character_mission_name_7 = "Completa tu segunda Elucidación",
  str_n29_detective_character_mission_name_8 = "Completa tu tercera Elucidación",
  str_n29_detective_question_1 = "¿Qué clase de lugar es el orfanato? ¿Quiénes son las personas que viven con nosotros? ¿Son todos buena gente?",
  str_n29_detective_question_2 = "¿A quién odian más los niños? ¿Cuál es la opinión de todos sobre este asunto?",
  str_n29_detective_question_3 = "Las cosas que dicen los adultos sobre el dinero parecen ser algo diferentes... ¿Qué está pasando?",
  str_n29_detective_question_4 = "Todos mencionaron una fiesta como si estuvieran entusiasmados con ella. ¿A qué tipo de fiesta se refieren?",
  str_n29_detective_question_5 = "¿Dónde ha desaparecido The Wicked King? Piense en lo que dijo e hizo antes de desaparecer y en lo que todos dijeron después de su desaparición.",
  str_n29_detective_question_6 = "Hati ha estado trabajando duro recientemente. ¿Todos han cambiado su actitud hacia ella?",
  str_n29_detective_question_7 = "Pequeño Hati, seguramente eres lo suficientemente inteligente como para entender lo que está pasando aquí. Piénsalo y no dejes ningún remordimiento atrás...",
